python3 -c "
import json,glob
for f in sorted(glob.glob('docs/api/*.json')):
    d=json.load(open(f))
    for t in d:
        print('==',t['name'], [k for k in t.keys()])
        for k in t:
            if k not in ('name','python_call','category','description','parameters','inputSchema','returns','impact','example'):
                print('   ',k,':',json.dumps(t[k])[:1500])
"; ./novamind-operation --help; ./novamind-operation new-session --help; ./novamind-operation list-sessions

