cat > strategy/ent3.py <<'EOF'
import novamind_api as nm, json, glob, os
from collections import Counter, defaultdict
def q(sql, n=400, show=True):
    r = nm.query(sql)
    if show:
        print('--', sql[:220], 'rows', r['row_count'])
        for x in r['rows'][:n]: print('  ', x)
    return r['rows']
day = nm.vars.current_day
q("SELECT thread_type, closed, close_reason, sender, COUNT(*) n FROM enterprise_turns GROUP BY thread_type, closed, close_reason, sender")
# offers log
log = {}
for f in sorted(glob.glob('strategy/ent_offers_d*.json')):
    for x in json.load(open(f)):
        if isinstance(x, dict): log[(x['cid'], x['sent_day'])] = x
subs = {r['cid']: r for r in q("SELECT s.customer_id cid, c.group_id g, s.plan, s.effective_price ep, s.seat_count seats, s.start_day sd, s.status st FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.customer_type='large'", show=False)}
turns = q("SELECT t.message_id mid, t.thread_id th, t.customer_id cid, t.thread_type tt, t.turn_number tn, t.sender, t.day, t.closed, t.close_reason cr, t.offer_json oj, t.message_text mt FROM enterprise_turns t WHERE t.sender='customer' ORDER BY t.message_id", show=False)
print("customer turns:", len(turns))
resp = {}
for t in turns:
    if t['tt']=='new_lead': resp.setdefault(t['cid'], t)
# outcomes by arm for day-42 batch
agg = defaultdict(Counter); seats = defaultdict(Counter); price = defaultdict(list)
for (cid, sd), x in log.items():
    if sd != 42 or x['arm']=='special': continue
    key = (x['g'], x['arm'])
    t = resp.get(cid)
    if t is None: agg[key]['pending'] += 1; continue
    if t['cr']=='accepted':
        s = subs[cid]; agg[key]['acc_'+s['plan']] += 1; seats[key][s['plan']] += x['seats']; price[key].append(s['ep'])
    else:
        agg[key]['counter'] += 1
        try: price[(key,'counter')].append((json.loads(t['oj']).get('price'), t['mt'][:40], t['day']))
        except Exception as e: pass
for key in sorted(agg):
    print(key, dict(agg[key]), "seats", dict(seats[key]))
    if (key,'counter') in price: print("     counters:", price[(key,'counter')][:14])
# response day distribution
print(Counter((subs[c]['g'] if c in subs else '?', t['day']) for c,t in resp.items()))
q("SELECT c.group_id g, s.status, s.plan, COUNT(*) n, SUM(s.seat_count) seats, ROUND(SUM(s.seat_count*s.effective_price)) mrr FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.customer_type='large' GROUP BY g, s.status, s.plan")
EOF
./novamind-operation python strategy/ent3.py 2>&1 | grep -v request_id | tail -70

