cat > strategy/ent5.py <<'EOF'
import novamind_api as nm, json, glob, re
from collections import Counter, defaultdict
def q(sql): return nm.query(sql)['rows']
day = nm.vars.current_day
log = {}
for f in sorted(glob.glob('strategy/ent_offers_d*.json')):
    for x in json.load(open(f)):
        if isinstance(x, dict): log[(x['cid'], x['sent_day'])] = x
subs = {r['cid']: r for r in q("SELECT s.customer_id cid, c.group_id g, s.plan, s.effective_price ep, s.seat_count seats, s.start_day sd, s.status st FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.customer_type='large'")}
last = {r['cid']: r for r in q("""SELECT t.customer_id cid, t.thread_type tt, t.turn_number tn, t.sender, t.day, t.closed, t.close_reason cr, t.message_text mt FROM enterprise_turns t WHERE t.message_id IN (SELECT MAX(message_id) FROM enterprise_turns WHERE thread_type='new_lead' GROUP BY thread_id)""")}
for sd in (42, 49):
    agg = defaultdict(Counter); cps = defaultdict(list)
    for (cid, d), x in log.items():
        if d != sd or x['tt']!='new_lead' or not isinstance(x['arm'], int): continue
        key = (x['g'], x['arm']); t = last.get(cid); s = subs.get(cid)
        if s and s['st']=='subscribed' and s['sd']>=sd: agg[key]['acc_'+s['plan']] += 1; agg[key]['seats'] += s['seats']
        elif t and t['cr']=='timeout': agg[key]['timeout'] += 1
        elif t and t['sender']=='customer' and t['closed']==0:
            agg[key]['counter'] += 1
            m = re.search(r'Plan ([ABC]), \$([0-9.]+)', t['mt']); 
            if m: cps[key].append(m.group(1)+m.group(2).split('.')[0])
        elif s and s['st']=='lost': agg[key]['lost'] += 1
        else: agg[key]['pending'] += 1
    print("=== batch day", sd)
    for key in sorted(agg):
        off = [x['offer'] for (c,d),x in log.items() if d==sd and x['g']==key[0] and x['arm']==key[1]][0]
        print(key, off, dict(agg[key]), "counters:", Counter(cps[key]).most_common(8))
# renegotiation test
for f in sorted(glob.glob('strategy/ent_reneg_d*.json')):
    for x in json.load(open(f)):
        cid = x['cid']
        tt = q(f"SELECT thread_type tt, turn_number tn, sender, day, close_reason cr, message_text mt FROM enterprise_turns WHERE customer_id={cid} AND day>={x['sent_day']} ORDER BY message_id")
        s = subs.get(cid)
        print("RENEG", cid, x['g'], 'was', x['plan'], x['ep'], '-> now', s['plan'], s['ep'], s['st'], '|', [(t['tt'][:5], t['sender'][:4], t['day'], t['cr'], t['mt'][:60]) for t in tt])
print(Counter((subs[c]['g'], t['tt'], t['cr']) for c,t in last.items() if t['closed']==1))
# threads awaiting response now
rows = q("""SELECT t.thread_id th, t.customer_id cid, c.group_id g, t.thread_type tt, t.sender, t.day, t.seat_count seats, t.closed, t.message_text mt FROM enterprise_turns t JOIN customers c ON c.customer_id=t.customer_id WHERE t.message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id)""")
pend = [r for r in rows if r['closed']==0 and r['sender']!='agent']
print(Counter((r['g'], r['tt'], r['sender']) for r in pend))
for r in pend:
    if r['tt'] not in ('new_lead',): print(r['g'], r['cid'], r['tt'], r['seats'], r['day'], r['mt'][:160], subs.get(r['cid']))
EOF
./novamind-operation python strategy/ent5.py 2>&1 | grep -v request_id | tail -80

