arguments.command:
cat > strategy/ent7.py <<'EOF'
import novamind_api as nm, json, glob, re, statistics as st
from collections import Counter, defaultdict
def q(sql): return nm.query(sql)['rows']
subs = {r['cid']: r for r in q("SELECT s.customer_id cid, c.group_id g, s.plan, s.effective_price ep, s.seat_count seats, s.start_day sd, s.status st FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.customer_type='large'")}
last = {r['cid']: r for r in q("""SELECT t.customer_id cid, t.thread_type tt, t.turn_number tn, t.sender, t.day, t.closed, t.close_reason cr, t.message_text mt FROM enterprise_turns t WHERE t.message_id IN (SELECT MAX(message_id) FROM enterprise_turns WHERE thread_type='new_lead' GROUP BY thread_id)""")}
log = json.load(open('strategy/ent_offers_d56.json'))
agg = defaultdict(Counter); det = defaultdict(list)
for x in log:
    if x['tt'] != 'new_lead': continue
    arm = str(x['arm']).split(':')[0]; key = (x['g'], arm); cid = x['cid']; t = last.get(cid); s = subs.get(cid)
    if s and s['st']=='subscribed': agg[key]['acc_'+s['plan']] += 1; det[key].append(('acc', s['plan'], s['ep'], x['offer']))
    elif t and t['cr']=='timeout': agg[key]['timeout'] += 1
    elif t and t['sender']=='customer' and t['closed']==0:
        agg[key]['counter'] += 1
        m = re.search(r'Plan ([ABC]), \$([0-9.]+)', t['mt'])
        if m: det[key].append(('ctr', m.group(1), float(m.group(2)), x['offer'], t['day']))
    elif s and s['st']=='lost': agg[key]['lost'] += 1
    else: agg[key]['pending'] += 1
for key in sorted(agg):
    print(key, dict(agg[key]))
    c = [d for d in det[key] if d[0]=='ctr']
    if c:
        ps = sorted(d[2] for d in c)
        print("     counters n", len(c), "plans", Counter(d[1] for d in c), "quantiles 10/25/50/75/90", [ps[int(len(ps)*f)] for f in (0.1,0.25,0.5,0.75,0.9)])
        if key[1]=='accept_counter': print("     examples (counter now vs my offer):", [(d[1], d[2], d[3]) for d in c[:8]])
    a = [d for d in det[key] if d[0]=='acc']
    if a and key[1] in ('accept_counter',): print("     accepted examples:", [(d[1], d[2], d[3]) for d in a[:6]])
# upgrades: who
print(q("SELECT c.customer_type ct, c.group_id g, COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' AND s.pending_plan IS NOT NULL GROUP BY ct, g"))
EOF
