cat > strategy/s1_daily.py <<'EOF'
import novamind_api as nm
day = nm.vars.current_day
for g in ('S1', 'D_S03', 'D_S07', 'D_S02', 'D_S10', 'D_S09', 'S2'):
    c = {r['d']: r['n'] for r in nm.query(f"SELECT s.end_day d, COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.group_id='{g}' AND s.status='cancelled' AND s.end_day>{day-10} GROUP BY 1")['rows']}
    # renewals due by day: subscribed with billing_day_mod30 == d%30 (survivors) 
    surv = {r['b']: r['n'] for r in nm.query(f"SELECT s.billing_day_mod30 b, COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.group_id='{g}' AND s.status='subscribed' AND s.start_day<={day-10} GROUP BY 1")['rows']}
    n = {(r['d'], r['plan']): r['n'] for r in nm.query(f"SELECT s.start_day d, s.plan, COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.group_id='{g}' AND s.start_day>{day-10} AND s.status IN ('subscribed','cancelled') GROUP BY 1,2")['rows']}
    print(g)
    for d in range(day-9, day+1):
        cc = c.get(d, 0); sv = surv.get(d % 30, 0)
        print('   day', d, 'cancels', cc, 'survivors', sv, 'churn %.0f%%' % (100*cc/max(cc+sv,1)), '| new A/B/C', n.get((d,'A'),0), n.get((d,'B'),0), n.get((d,'C'),0))
EOF
