import novamind_api as nm, json, re
from collections import Counter
log = {l['cid']: l for l in json.load(open('strategy/reneg_b_d427.json'))}
off = {l['cid']: l for l in json.load(open('strategy/ent_offers_d434.json')) if l['tt']=='renegotiation'}
rows = nm.query("""SELECT t.thread_id th, t.customer_id cid, t.turn_number tn, t.sender, t.day, t.closed, substr(t.message_text,1,80) mt
FROM enterprise_turns t WHERE t.thread_type='renegotiation' AND t.day>=427 ORDER BY t.message_id LIMIT 4900""")['rows']
ths = {}
for r in rows: ths.setdefault(r['th'], []).append(r)
c = Counter(); ex = []
for th, v in ths.items():
    cid = v[0]['cid']; o = off.get(cid)
    if not o: 
        last = v[-1]
