ent2 = nm.query("SELECT s.customer_id cid, c.group_id g, s.seat_count*s.effective_price rev, s.billing_day_mod30 b FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.customer_type='large' AND s.status='subscribed' LIMIT 4990 OFFSET 4990")['rows']
