        close = max(base + LAG.get(r['g'], 12), day + 1)
    for d in range(day + 1, 501):
        if d % 30 == r['b']:
            if close is not None and d <= close: susp[d] += r['rev']
            else: ent_rev[d] += r['rev'] * (ACC if t else 1.0)
# individuals: renewals by billing day, retention per group from last 3 days
ind = nm.query("SELECT c.group_id g, s.billing_day_mod30 b, SUM(s.effective_price) rev FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.customer_type='small' AND s.status='subscribed' GROUP BY 1,2")['rows']
can = {r['g']: r['rev'] for r in nm.query(f"SELECT c.group_id g, SUM(s.effective_price) rev FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.customer_type='small' AND s.status='cancelled' AND s.end_day>{day-3} GROUP BY 1")['rows']}
ren = defaultdict(float)
for r in ind:
    if r['b'] in ((day-2) % 30, (day-1) % 30, day % 30): ren[r['g']] += r['rev']
ret = {g: ren[g] / max(ren[g] + can.get(g, 0), 1) for g in ren}
ov = json.loads(os.environ.get('RET', '{}')); ret.update(ov)
print('individual retention used:', {g: round(v, 2) for g, v in sorted(ret.items())})
new7 = nm.query(f"SELECT SUM(amount) c FROM ledger WHERE day>{day-7} AND category='subscription_payment'")['rows'][0]['c']
NEWD = float(os.environ.get('NEWD', 0.45e6))   # daily revenue from new signups (first payments)
ind_rev = defaultdict(float)
for r in ind:
    for d in range(day + 1, 501):
        if d % 30 == r['b']:
